import React from 'react';
import { createRoot } from 'react-dom/client';
import Header from "./components/Header";
import Body from "./components/Body";
import About from "./components/About";
import Error from "./components/Error";
import Contacts from "./components/Contacts";
import RestaurantMenu from "./components/RestaurantMenu";

import { createBrowserRouter, RouterProvider, Outlet } from 'react-router-dom';

/*
    1. Header
        - Logo
        - Nav Items
    2. Body
        - Search
        - Restaurant Card
    3. Footer
        - Copyright
        - Links
        - Address
        - Contact
*/

const AppLayout = () => {
    return <div className="app">
        <Header/>
        <Outlet/>
    </div>
}

//Router Configuration
const appRouter = createBrowserRouter([
    {
        path: "/",
        element : <AppLayout/>,
        children: 
        [
            {
                path: "/",
                element: <Body/>,
            },
            {
                path: "/about",
                element: <About/>,
            },
            {
                path: "/contacts",
                element: <Contacts/>,
            },
            {
                path: "/restaurant/:resId", //: - used for dynamic routing (resId is a param which differentiates the restaurants)
                element: <RestaurantMenu/>
            },
        ],
        errorElement: <Error/>,//shows error page
    },
    
])
const root = createRoot(document.getElementById("root"));

//Providing router configuration(appRouter) to the AppLayout
root.render(<RouterProvider router={appRouter}/>);

const About = () => {
    return (
    <div className="about">
        <h2>About us</h2>
    </div>)
}

export default About;

import RestaurantCard from "./RestaurantCard";
import {SWIGGY_API_URL} from "../utils/constant";
import {useState, useEffect} from "react";
import Shimmer from "./Shimmer";
import {Link} from "react-router-dom";

//2. Body Component
const Body = () => {
    //Local state variable = Super powerful variable
    const [listOfRestaurants, setListOfRestaurants] = useState([]);//All Restaurants
    const [filteredRestaurants, setFilteredRestaurants] = useState([]); //Filtered Restaurants
    const [searchRestaurant, setSearchRestaurant] = useState("");//Search Restaurants

    //useEffect(2 params) - callback function, dependencies
    useEffect(() => {
        getRestaurants();
    }, []);

    //get restaurants list
    const getRestaurants = async () => {
        //making swiggy api call
        const data = await fetch(SWIGGY_API_URL);
        const json = await data.json();

        setListOfRestaurants(json?.data?.cards[5]?.card?.card?.gridElements?.infoWithStyle?.restaurants);
        setFilteredRestaurants(json?.data?.cards[5]?.card?.card?.gridElements?.infoWithStyle?.restaurants);
    };//getRestaurants

    if(listOfRestaurants.length === 0)
        return <Shimmer/>

    return ( <div className="body">
       <div className="filter">
            <input type="text" value={searchRestaurant}
                onChange={(e) => {
                    setSearchRestaurant(e.target.value);
                    const filteredRes = listOfRestaurants.filter((res) => 
                    { 
                        return res.info.name.toLowerCase().includes(searchRestaurant.toLowerCase())
                    })
                    
                    setFilteredRestaurants(filteredRes);
                }}
            />
            {/* <button className="res-search" onClick={() => 
            {
                const filteredRes = listOfRestaurants.filter((res) => 
                { 
                    return res.info.name.toLowerCase().includes(searchRestaurant.toLowerCase())
                })
                
                setFilteredRestaurants(filteredRes);
            }}>
            Search
            </button> */}

            <button className="res-filter" onClick={() => 
                {
                    const filteredList = listOfRestaurants.filter((restaurants) => restaurants.info.avgRating > 4);
                    setFilteredRestaurants(filteredList);//updating the state
                }}>
                Top Rated Restaurants
            </button>
       </div>
        <div className="res-container">
            {
                (searchRestaurant.length > 0) ?
                //showing only filtered restaurants
                filteredRestaurants.map((restaurant) => (
                    <RestaurantCard key={restaurant.info.id} resData={restaurant}/>
                ))
                : 
                //showing all the restaurants
                listOfRestaurants.map((restaurant) => (
                    <Link to={"/restaurant/" + restaurant.info.id} 
                        key={restaurant.info.id}>
                        <RestaurantCard key={restaurant.info.id} resData={restaurant}/>
                    </Link>
                    // <RestaurantCard key={restaurant.info.id} resData={restaurant}/>
                ))
            }
        </div>
    </div>
    )
}

export default Body;

const Contacts = () => {
    return ( 
        <div className="contacts">
            <h2>Contacts</h2>
        </div>
    )
}

export default Contacts;

import { useRouteError } from "react-router-dom";

const Error = () => {
    const error = useRouteError();
    console.log(error);
    return (
    <div className="error">
        <h2>OOPs!</h2>
        <h3>Something went wrong</h3>
        <h3>{error.status} : {error.statusText}</h3>
    </div>)
}

export default Error;

import {CDN_URL} from "../utils/constant";

//3. Restaurant Card
const RestaurantCard = (props) => {
    const {resData} = props;

    return (<div className="res-card">
        <img className="res-logo" src={CDN_URL+resData.info.cloudinaryImageId}/>
        <h3>{resData.info.name}</h3>
        <h4>{resData.info.cuisines.join(", ")}</h4>
        <h4>{resData.info.avgRating} stars</h4>
        <h4>{resData.info.sla.deliveryTime} mins</h4>
        <h4>{resData.info.costForTwo}</h4>
    </div>);
}

export default RestaurantCard;

import { useState, useEffect } from "react";
import {SWIGGY_MENU_API_URL} from "../utils/constant";
import { useParams } from "react-router-dom";
import Shimmer from "./Shimmer";

const RestaurantMenu = () => {
    const {resId} = useParams();//call useParam to get value of restaurant Id(resId) using object destructuring.
    const [restaurant, setRestaurant] = useState(null);//holds a restaurant details

    //calls only once after the initial component render
    useEffect(() => {
        getRestaurantInfo();
    }, []);

    //get restaurant details
    const getRestaurantInfo = async () => {
        const restaurantData = await fetch(SWIGGY_MENU_API_URL + resId);//fetching menu data
        const jsonResData = await restaurantData.json();//converting fetched data to json
        
        //set restaurant
        setRestaurant(jsonResData.data);
    }

    if(restaurant === null) return <Shimmer/>;

    //destructuring the restaurant info
    const {name, cuisines, costForTwoMessage, locality, avgRating, totalRatingsString
    } = restaurant?.cards[0]?.card?.card?.info;
    const {deliveryTime} = restaurant?.cards[0]?.card?.card?.info.sla;
    
    console.log(restaurant?.cards[0]?.card?.card?.info)

    //menu
    const {itemCards} = restaurant?.cards[2]?.groupedCard?.cardGroupMap?.REGULAR?.cards[3]?.card?.card;
    // console.log(itemCards);
    return ( 
    <div className="res-details">
        <section className="res-header">
            <div>
                <h1>{name}</h1>
                <p>{cuisines.join(", ")} </p>
                <p>{locality}</p>
            </div>
            <div className="res-rating">
                <h2>⭐{avgRating}</h2>
                <hr/>
                <h4>{totalRatingsString}</h4>
            </div>
        </section>
        <hr/>
        <section className="res-deliveryInfo">
            <h3>🕗{deliveryTime}</h3>
            <p>💵{costForTwoMessage}</p>
        </section>
        <hr/>
        <section className="res-recomends">
            <h2>Recommended ({itemCards.length})</h2>
            <ul>
            {
                itemCards.map((item) => (
                    <li key={item.card.info.id}>
                        <h3>{item.card.info.name}</h3>
                        <p>{" Rs."} {item.card.info.price/100 || item.card.info.defaultPrice/100}</p>
                    </li>
                ))
            }
            </ul>
        </section>
    </div>)

}

export default RestaurantMenu;

/* Header component starts */
